Import ListNotations.
Open Scope Z_scope.

Definition ATDLOC : Z := 0x6c3ee8.

Definition TDW : Z * Z := (ATDLOC, ATDLOC + 8).

Definition td_law {HCEIL : HeapCeil} (H : asr) : Prop :=
  forall (s : as_St H) (LB : list block) (LF : list fframe) (B : Z) (m m' : mem),
    munch [(ATDLOC, ATDLOC + 8)] m m' -> wmono asegs m m' ->
    (as_RHEAP H s LB m -> as_RHEAP H s LB m') /\ (as_RFS H LF m -> as_RFS H LF m') /\ (as_rauxv_ok H m B -> as_rauxv_ok H m' B).
Definition is_tdw (iv : Z * Z) : bool := ((fst iv =? ATDLOC) && (snd iv =? ATDLOC + 8))%bool.

Fixpoint td_free (W : list (Z * Z)) : list (Z * Z) :=
  match W with [] => [] | iv :: W' => if is_tdw iv then td_free W' else iv :: td_free W' end.

Lemma td_wview : forall (M : mem) (x : word), ATDLOC <= bv_unsigned x < ATDLOC + 8 -> wview asegs M x <> None.
